const CURRENCY_NAME_KEYS = Object.freeze({
    CNY: "currCNY",
    USD: "currUSD",
    EUR: "currEUR",
    JPY: "currJPY",
    GBP: "currGBP",
    KRW: "currKRW",
    HKD: "currHKD",
    TWD: "currTWD",
    SGD: "currSGD",
    AUD: "currAUD",
    CAD: "currCAD",
    CHF: "currCHF",
    THB: "currTHB",
    RUB: "currRUB",
    INR: "currINR",
    XAU: "currXAU",
    BTC: "currBTC"
});
export function getCurrencyName(code, fallback) {
    const key = CURRENCY_NAME_KEYS[code];
    return key ? t(key) : (fallback ?? code);
}
